var t=()=>{if(!("serviceWorker"in navigator))return;let e=document.querySelector('meta[name="filament-pwa-service-worker"]')?.content,r=document.querySelector('meta[name="filament-pwa-scope"]')?.content;!e||!r||navigator.serviceWorker.register(e,{scope:r,updateViaCache:"none"}).catch(n=>{console.error("Unable to register the Filament PWA service worker.",n)})};document.readyState==="loading"?document.addEventListener("DOMContentLoaded",t,{once:!0}):t();
